window.DIGEST.foryou.push(...[{"id": "2112588276175708409", "url": "https://x.com/urdeaintech/status/2112588276175708409", "text": "AI made it easy for every brand to post, and now every AI image looks the same\n\npeople can tell. design has honestly gotten worse for it\n\nVyb is AI too, but it starts from your brand instead of the average:\n\n→ your real logo, fonts and colors\n→ your product photo, never redrawn\n→ every element on its own layer, so you can edit just the headline", "name": "Samuel Urdea", "handle": "urdeaintech", "avatar": "https://pbs.twimg.com/profile_images/2092899894218416128/ZypwJ5s7_200x200.jpg", "likes": 62, "rts": 1, "replies": 0, "views": 472, "ts": 1792515269, "media": [], "quote": {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1822098, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.23, "thread": [], "tier": "worth"}, {"id": "2112453025843564855", "url": "https://x.com/Ivybest666/status/2112453025843564855", "text": "天啊，开眼了！\n\n这台缝纫机已经超出了我的认知范畴……\n\n这种极致的无痕修复，\n\n简直是失传级别的神级手艺！\n\n现在还有多少人会这种绝活？", "name": "Ivy", "handle": "Ivybest666", "avatar": "https://pbs.twimg.com/profile_images/2076614500967714816/twy7C20f_200x200.jpg", "likes": 13235, "rts": 544, "replies": 386, "views": 11202379, "ts": 1792483023, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112452669675814912/vid/avc1/480x752/nLTBkTuAZbDZ5rvP.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112452669675814912/vid/avc1/720x1130/42N5QPT1ydphZ2nu.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112452669675814912/img/oysDf3hv7trjU8nI.jpg", "dur": 234}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112584712145281466", "url": "https://x.com/whemohere/status/2112584712145281466", "text": "HOLY F*CK, I SET UP LAUREN TAN'S DR. EGGBOT BY THE GROK BOT TEAM'S OWN PLAYBOOK. ONE PROMPT AND IT DESIGNED MY WHOLE BOT TEAM, THEN WAITED FOR MY YES\n\nlauren tan is a designer on the grok bot team. dr. eggbot is her bot for building other bots.\n\nwhat it did in 14 minutes:\n→ read my brief, AGENTS.md, ANTIPATTERNS.md and the roster\n→ restated my job back to me before touching anything\n→ proposed 6 bots: chief of staff, inbox, faq desk, leads, call prep, misc\n→ gave each one an access list and one thing it can never do\n→ attached 12 rules, like \"attach proof to every result\"\n→ created 0 until I typed yes\n\nthe part I'd copy even without eggbot: every bot gets a \"never\" line. inbox never sends without me. leads never contacts anyone.\n\npaste this into grok bot:\n\"Design my bot team. Read AGENTS.md, ANTIPATTERNS.md and roster/README.md first. Restate my job in 5 lines. Propose bots with access and one 'never' rule each. Create nothing until I say yes.\"\n\nthe full playbook with the repo is in the article below ↓", "name": "whemo", "handle": "whemohere", "avatar": "https://pbs.twimg.com/profile_images/2059310143922155521/6BrgqZML_200x200.jpg", "likes": 39, "rts": 1, "replies": 11, "views": 990, "ts": 1792514419, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112584496662925312/vid/avc1/720x900/-PWlHXl_x1Nw-dRq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112584496662925312/vid/avc1/2160x2700/MhDOrVFg5GpqQVsn.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112584496662925312/img/tpwYtCcGTHYkucc1.jpg", "dur": 25}], "quote": {"id": "2112574886421901822", "url": "https://x.com/unicodef1wn/status/2112574886421901822", "text": "I put together one guide for anyone who wants a workflow like the SpaceXSI team's.\n\nOne message builds your whole Grok Bot setup. Plus the team's rules, prompt habits, routines and permissions. Every setup is a block you paste.\n\n16-min read. Save it ↓ https://x.com/i/article/2112449845566877696", "name": "unicode", "handle": "unicodef1wn", "avatar": "https://pbs.twimg.com/profile_images/2069360360763576321/Id-DSoyU_200x200.jpg", "likes": 125, "rts": 3, "replies": 30, "views": 54763, "ts": 1792512077, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112531780674707552", "url": "https://x.com/NielsRogge/status/2112531780674707552", "text": "I've made some big improvements to the PDF reader on Papers with Code!\n\n> The AI assistant now cites its sources, full RAG-style\n> This is powered by Chandra-OCR 2 by @datalabto which is openly available on @huggingface \n> This model returns bounding boxes besides markdown\n> Allows you to click on citations and highlight sections\n\nTry it out on any PDF, like https://paperswithcode.co/pdf/2610.18861", "name": "Niels Rogge", "handle": "NielsRogge", "avatar": "https://pbs.twimg.com/profile_images/1828883496066060288/n0OUAXhz_200x200.jpg", "likes": 52, "rts": 4, "replies": 6, "views": 1909, "ts": 1792501800, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112531297922945024/vid/avc1/1118x720/n6Azd3LzvIfPF4-9.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112531297922945024/vid/avc1/3354x2160/dutOhT-TZXTefmy_.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112531297922945024/img/89ZnBg9VPNx01VmA.jpg", "dur": 45}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112564497105953123", "url": "https://x.com/EnvolDev/status/2112564497105953123", "text": "DeepSeek V4.1 Flash 1017 vs Minimax M3.1 Flash  \n\nSame prompt.  Same task.  \n\nDeepseek Time: 1 h 28 min 27 s Cost: $0,54  \nMinimax Time: 1 h 6 min 51 s Cost: $0,22  \n\nDeepseek wins again?", "name": "Tony", "handle": "EnvolDev", "avatar": "https://pbs.twimg.com/profile_images/2097356902397349888/X70_Yv_4_200x200.jpg", "likes": 45, "rts": 1, "replies": 10, "views": 1555, "ts": 1792509600, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112441644998127616/vid/avc1/720x720/0tgm99iXdJHQFyS1.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112441644998127616/vid/avc1/2880x2880/zkS9Py75HEx56wDO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112441644998127616/img/orUmEBCnXZXncjKH.jpg", "dur": 25}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112642557717237799", "url": "https://x.com/Arsenal/status/2112642557717237799", "text": "Building a rhythm.", "name": "Arsenal", "handle": "Arsenal", "avatar": "https://pbs.twimg.com/profile_images/2112455038769455104/MK7bavxB_200x200.jpg", "likes": 6847, "rts": 531, "replies": 28, "views": 150187, "ts": 1792528211, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112642519360266240/vid/avc1/720x1280/1lzphTyPiAXVAz3n.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112642519360266240/vid/avc1/1080x1920/g88iLVOg2T1IL7Lw.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112642519360266240/img/PkA2lflBeQkakIuO.jpg", "dur": 22}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112579239950393365", "url": "https://x.com/hari_arul/status/2112579239950393365", "text": "thrilled to co-lead this round with @vkhosla @SStrohband @khoslaventures . @bobmcgrewai is a singular leader, and we in the US could not be more fortunate he’s applying his energy to improving American manufacturing. congratulations!", "name": "Hari Arul", "handle": "hari_arul", "avatar": "https://pbs.twimg.com/profile_images/473232490136489984/sBvm-LJB_200x200.jpeg", "likes": 35, "rts": 4, "replies": 9, "views": 9243, "ts": 1792513115, "media": [], "quote": {"id": "2112558753770033342", "url": "https://x.com/bobmcgrewai/status/2112558753770033342", "text": "We started Arda in 2025 to speed up American manufacturing. We have spent the last year building with Anduril as our design partner. Today we are launching the company publicly on CNBC and announcing our Series A: $160M at a $1.5B valuation.\n\nOur platform helps manufacturers design and operate manual assembly lines, putting designs into production faster now. Next we'll build automated lines that can be reconfigured as quickly as human workers, letting America make products that now require armies of workers in Asia. https://x.com/Kr00ney/status/2112539896615518212/video/1", "name": "Bob McGrew", "handle": "bobmcgrewai", "avatar": "https://pbs.twimg.com/profile_images/1010746747637788672/lOWcy5c0_200x200.jpg", "likes": 494, "rts": 48, "replies": 65, "views": 91666, "ts": 1792508230, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112539858992578560/vid/avc1/610x360/7JUgkrX3H7hISkdg.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112539858992578560/vid/avc1/886x522/zYBXb4VeojaNP0yM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112539858992578560/img/zx0hDtXZBkoWYGAl.jpg", "dur": 36}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112604993714786684", "url": "https://x.com/karlarboledas/status/2112604993714786684", "text": "Most AI tools need your whole work history on someone else's server to remember anything.\n\nShogun:\n→ Keeps its memory local on the Mac\n→ Remembers yesterday's meeting\n→ Knows last week's draft\n→ Keeps track of today's docs\n\nPrivate by default, and it still remembers", "name": "karla", "handle": "karlarboledas", "avatar": "https://pbs.twimg.com/profile_images/2106955765348974592/5Ul1ntrn_200x200.jpg", "likes": 24, "rts": 8, "replies": 6, "views": 1424, "ts": 1792519255, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112604929399365632/vid/avc1/510x360/G5Hi8kruQ-fw1Wvm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112604929399365632/vid/avc1/1020x720/vERIQwUBJA4zg06T.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112604929399365632/img/9JlOnSOoqJNF0aRo.jpg", "dur": 26}], "quote": {"id": "2112593925114634603", "url": "https://x.com/toruai/status/2112593925114634603", "text": "Your AI forgets you every time you close it. \n\nEvery assistant today works the same way. You open a chat, re-explain your job, get an answer, and start from zero tomorrow.  Smart, sure. Useful? \n\nOnly while you're typing.  It doesn't know about yesterday's meeting. It does nothing until you ask. \n\nAnd most of them want your whole work history on someone else's server to remember it.  \n\nWe built Shogun for exactly this.\n@Shogun_AI_\nShogun is a private, local-first memory on your Mac. It remembers your meetings, drafts, and docs, then works while you sleep: prepares replies, organizes what it can, writes your daily brief.  You wake up, review, approve. \n\nNothing goes out without your yes. Your personal AGI, always running on your computer.\n\nThe first 500 users get a month free.\n\nFollow @Shogun_AI_ @toruai\nand comment 『ShogunAI』", "name": "Toru.T", "handle": "toruai", "avatar": "https://pbs.twimg.com/profile_images/2077537203614605312/9S3FfAKk_200x200.jpg", "likes": 87, "rts": 44, "replies": 51, "views": 21639, "ts": 1792516616, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112592786579189760/vid/avc1/1280x720/kJpS_CWA4h8yYETb.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112592786579189760/vid/avc1/3840x2160/0kg65h_VD_oWzGWC.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112592786579189760/img/uhPh59whRg063POW.jpg", "dur": 132}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112676295851303154", "url": "https://x.com/joeyxhong/status/2112676295851303154", "text": "very fitting first post ever from me! got to work with many cool and genuine people in building this model.\n\non another note @saurabh_shah2 and @parth_29, I think we should see other people for awhile.", "name": "Joey Hong", "handle": "joeyxhong", "avatar": "https://pbs.twimg.com/profile_images/2112580657780334593/QE4WVEcr_200x200.jpg", "likes": 28, "rts": 4, "replies": 4, "views": 1409, "ts": 1792536255, "media": [], "quote": {"id": "2112674550907552137", "url": "https://x.com/humansand/status/2112674550907552137", "text": "No one changes the world alone\nIntroducing Ampersand - the first model built for us. Ampersand is a collaborator trained to help people achieve their individual and collective goals. In multi-month simulations, users collaborating with Ampersand accomplished more than with Fable and other frontier models\nAvailable to everyone through our API", "name": "humans&", "handle": "humansand", "avatar": "https://pbs.twimg.com/profile_images/2013582555933478912/JKuMlTII_200x200.jpg", "likes": 801, "rts": 96, "replies": 70, "views": 115146, "ts": 1792535839, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1280x720/diVwgP2fN9mNUINm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112664844772278272/vid/avc1/1920x1080/BeqyLOSxKBxRevC6.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112664844772278272/img/eMd4u-rAwyUJpqWU.jpg", "dur": 32}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.22, "thread": [], "tier": "worth"}, {"id": "2112549486715380018", "url": "https://x.com/TimJayas/status/2112549486715380018", "text": "i'm afraid the only response openai has for fable 5.5 is a banked limit reset", "name": "Tim Jayas", "handle": "TimJayas", "avatar": "https://pbs.twimg.com/profile_images/2016190209768226821/MW5mAfL-_200x200.jpg", "likes": 61, "rts": 0, "replies": 5, "views": 2289, "ts": 1792506021, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.21, "thread": [], "tier": "worth"}, {"id": "2112575067171553419", "url": "https://x.com/yohakujpn/status/2112575067171553419", "text": "i found 8 GitHub repos that turn your AI agent into an analyst desk\n\nit reads SEC filings, spots what quietly changed, hunts supply chain bottlenecks\n\nthe work funds pay analysts for 👇                                                                                                                                                                                                         \n\n1/ data\n\nequibles: your own financial data server for agents. SEC filings, XBRL, 68 MCP tools, no key\n\nhttp://github.com/daniel3303/Equibles\n\nagentii: 1,146+ US companies with full SEC history, 80 skills. needs one API key\n\nhttp://github.com/agentii-ai/agentii-investment-intelligence\n\n2/ reading filings\n\nedgar-change-interpreter: what changed or quietly disappeared between 10-K, 10-Q and 8-K\n\nhttp://github.com/cmdrvl/edgar-change-interpreter\n\noddly: finds odd-lot tender offers in SEC filings. holders of 99 shares or fewer get priority\n\nhttp://github.com/KorroAi/oddly\n\n3/ finding ideas\n\nserenity-bottleneck-hunter: give it a theme, it maps the supply chain and finds overlooked upstream bottlenecks. built on @aleabitoreddit's public method\n\nhttp://github.com/Mrjie7205/serenity-bottleneck-hunter\n\nbuffett-letters-skill: 60+ years of Buffett's letters as 20 decision modules\n\nhttp://github.com/kangarooking/buffett-letters-skill\n\n4/ rules\n\nclaude-trading-skills: market review, risk, trade plans, journal. no signals\n\nhttp://github.com/tradermonty/claude-trading-skills\n\nfinance_skills: 91 skills across 7 plugins. portfolio management, compliance, advisory\n\nhttp://github.com/JoelLewis/finance_skills\n\nnot financial advice. they do the research, the decision stays yours\n\nsave this before the next earnings season", "name": "Yohaku", "handle": "yohakujpn", "avatar": "https://pbs.twimg.com/profile_images/2083104990667677696/7gP07-3Z_200x200.jpg", "likes": 37, "rts": 4, "replies": 8, "views": 878, "ts": 1792512120, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112498682239016960/vid/avc1/1280x720/Vgz8oDKvONk7e2ak.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112498682239016960/vid/avc1/1920x1080/d96_bICPngQyeow-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112498682239016960/img/FMtEgm8N1nkTrzLo.jpg", "dur": 16}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.21, "thread": [], "tier": "worth"}, {"id": "2112594565266043212", "url": "https://x.com/mitesh711/status/2112594565266043212", "text": "We're scaling with @general_compute . GC is purchasing @positron_ai Atlas and committing to our next gen Titan over a multi year agreement, expanding its inference offering and bringing Positron to more cloud customers. Atlas available through GC in Q1 2027. A big growth milestone for both teams. Ty @FPuklowski @GoodisonJason - this team is special.", "name": "Mitesh Agrawal", "handle": "mitesh711", "avatar": "https://pbs.twimg.com/profile_images/1140695228556271616/73FBaO-l_200x200.jpg", "likes": 39, "rts": 3, "replies": 6, "views": 1369, "ts": 1792516769, "media": [], "quote": {"id": "2112585266854604957", "url": "https://x.com/general_compute/status/2112585266854604957", "text": "Our heterogeneous cloud just got better. We're announcing a cluster scale deployment of @positron_ai as our next partner.\n\nWe believe demand for fast inference will outstrip supply for the next decade. Our bet on Positron is another step towards getting fast inference for opensource models into builders' hands.\n\nHardware goes live Q1 2027.\n\nThanks to @mitesh711, @trsohmers and the whole Positron team! We're excited for this partnership.\n\nLFG!", "name": "General Compute", "handle": "general_compute", "avatar": "https://pbs.twimg.com/profile_images/2063265967774584832/y1U0qHB3_200x200.jpg", "likes": 830, "rts": 58, "replies": 108, "views": 234978, "ts": 1792514552, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112585087921377280/pu/vid/avc1/640x360/KX7QPT-I86P0SW2r.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112585087921377280/pu/vid/avc1/1280x720/XBFGYfCEY_EsyfiI.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112585087921377280/pu/img/EYiImymSTr1OyRJQ.jpg", "dur": 47}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.21, "thread": [], "tier": "worth"}, {"id": "2112725613056602509", "url": "https://x.com/aiedge_/status/2112725613056602509", "text": "This website is a goldmine.\n\nHundreds of Opus 5.5 motion videos, skills, graphics, extras & more.\n\nAll are free to download & inject into your agents.\n\n👉 https://motionvideo.xyz/", "name": "AI Edge", "handle": "aiedge_", "avatar": "https://pbs.twimg.com/profile_images/1910271186442846208/vrYKSYRn_200x200.jpg", "likes": 28, "rts": 4, "replies": 0, "views": 2817, "ts": 1792548013, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112725563513413632/vid/avc1/1746x720/xZDlq_l7fM8vDaLZ.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112725563513413632/vid/avc1/2620x1080/JMMzr1N3rYZ7-CdI.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112725563513413632/img/BqL2qYbzgMUL0pdH.jpg", "dur": 7}], "quote": {"id": "2112552093483671966", "url": "https://x.com/aiedge_/status/2112552093483671966", "text": "https://x.com/i/article/2112269769747693568", "name": "AI Edge", "handle": "aiedge_", "avatar": "https://pbs.twimg.com/profile_images/1910271186442846208/vrYKSYRn_200x200.jpg", "likes": 81, "rts": 10, "replies": 5, "views": 28743, "ts": 1792506643, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.21, "thread": [], "tier": "worth"}, {"id": "2112634805615468998", "url": "https://x.com/jpmorgan/status/2112634805615468998", "text": "As our Security and Resiliency Initiative marks its first anniversary, Doug Petno and Jay Horine reflect on what we’ve accomplished and what’s next.\n\nThis conversation launches a new video series featuring leaders from across the initiative, sharing perspectives on the challenges, opportunities and investments shaping a more resilient future. \n\nWatch the first episode — and stay tuned for more. http://spr.ly/6017BHpxLP", "name": "J.P. Morgan", "handle": "jpmorgan", "avatar": "https://pbs.twimg.com/profile_images/1605200105799401474/9cb5qdVk_200x200.png", "likes": 25, "rts": 6, "replies": 5, "views": 5305, "ts": 1792526363, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112634744919801856/vid/avc1/720x1280/vWNWuunMMssZdylf.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112634744919801856/vid/avc1/1080x1920/DiOnrCyg4zztp92K.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVGWKIYXgAA8smt.jpg", "dur": 24}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.21, "thread": [], "tier": "worth"}, {"id": "2112643906244427838", "url": "https://x.com/karlarboledas/status/2112643906244427838", "text": "Clean eating, filtered water, better sleep. Home air rarely makes the wellness list.\n\nThe P1 from @BreethrHQ:\n→ Brings outdoor air in\n→ Filters it\n→ Cools it\n→ Indoor unit built to look good at home\n\nIndoor air finally on the list", "name": "karla", "handle": "karlarboledas", "avatar": "https://pbs.twimg.com/profile_images/2106955765348974592/5Ul1ntrn_200x200.jpg", "likes": 15, "rts": 9, "replies": 5, "views": 826, "ts": 1792528532, "media": [], "quote": {"id": "2112589671087980605", "url": "https://x.com/abhinavguptaIAQ/status/2112589671087980605", "text": "For the last ten years I have spent every moment thinking about nothing but air. And how to make better, more personalized air accessible to homes all over the world.\n\nAnd today I can finally present the next huge step in that journey.\n\nIntroducing Breethr P1, the Personal Climate System.\n\nLaunching today. And open for pre-orders right now\n\nReserve your P1 for $99: https://breethr.com\n\nShipping Spring 2027.", "name": "Abhinav Gupta", "handle": "abhinavguptaIAQ", "avatar": "https://pbs.twimg.com/profile_images/2111897274586718208/4AVe2tev_200x200.jpg", "likes": 1416, "rts": 241, "replies": 221, "views": 1597959, "ts": 1792515602, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112513854957928448/vid/avc1/1330x720/uNPFmr9TjO0A86uW.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112513854957928448/vid/avc1/3840x2076/i_VMXGYtZhk0cfwG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112513854957928448/img/p7tmfJApNOoQG8uy.jpg", "dur": 234}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.21, "thread": [], "tier": "worth"}, {"id": "2112651652566020582", "url": "https://x.com/Solomonrojie/status/2112651652566020582", "text": "THIS IS A PURE F*CKING TREASURE\n\nSpaceXAI just documented one of the best setups for Grok Bot\n\nthe idea: keep the working chat short, save useful research in files, and let code handle routine checks before the bot starts thinking\n\n100,000 → 12,500 tokens per task. the same budget goes from 7 usable results to 70 because less of it disappears into repeated work\n\nyou start Grok Bot like this:\n\n“Set up this workflow to reuse completed work, read only relevant sources, and check every result before calling it done.”\n\nhere’s how it splits:\n\n→ Grok Bot defines the task, makes the decisions, and produces the finished result\n→ saved files hold confirmed facts, previous findings, and the next action\n→ scripts search, filter, compare versions, and check whether anything changed\n→ verification catches failed requirements and returns specific corrections before you see the result\nfresh research only starts in three moments:\n→ no saved result answers the question\n→ a relevant source or input changed\n→ an important fact has expired or can’t be verified\n\nfiles remember. code filters. Grok Bot finishes\n\nthe same principle applies to a whole team: one owner per task, short handoffs, and no second bot rebuilding research the first one already completed\n\nthe full tree:\n→ save the goal, decisions, and next action in HANDOFF.md\n→ start the next task in a fresh chat using that file\n→ search sources before opening entire documents\n→ check for changes before running a full investigation\n→ reuse valid results and refresh only affected findings\n→ stop failed operations after 2 attempts and preserve completed work\n→ check the output against the brief, then fix only what failed\n\npaste the tree and this prompt into Grok Bot ↓\n\n“Reconfigure my workflow around this setup:\n\n1/ Review recent runs and identify the biggest source of repeated work.\n\n2/ Create BRIEF.md, HANDOFF.md, sources/, results/, and a run log. Keep the working context short.\n\n3/ Search saved results first. Retrieve relevant passages, check freshness, and update only what changed.\n\n4/ Give each task one owner. Save progress and stop the same failing operation after 2 attempts.\n\n5/ Check every result against the brief. Allow one focused correction pass, then flag anything unresolved.\n\nShow me the proposed changes and test one real task before scheduling it.”\n\nsave it before your next upgrade\n\nthe full course below walks through all 7 fixes, with tools, ready-to-copy files, and the complete workflow ↓", "name": "Solomon Rojie", "handle": "Solomonrojie", "avatar": "https://pbs.twimg.com/profile_images/2073858581804322816/9CJNyjNy_200x200.jpg", "likes": 32, "rts": 2, "replies": 6, "views": 895, "ts": 1792530379, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112651522978783232/vid/avc1/720x902/zZA8_IVkJVYoQ9wj.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112651522978783232/vid/avc1/1530x1920/WNkEMGlvjQdyGq8c.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112651522978783232/img/H-_OgXjwDa2d7w7B.jpg", "dur": 26}], "quote": {"id": "2112214741103825314", "url": "https://x.com/Greshamtrade/status/2112214741103825314", "text": "https://x.com/i/article/2112211009951670272", "name": "Gresham", "handle": "Greshamtrade", "avatar": "https://pbs.twimg.com/profile_images/2081690044461457408/I9NHHTUW_200x200.jpg", "likes": 108, "rts": 10, "replies": 17, "views": 88628, "ts": 1792426211, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.21, "thread": [], "tier": "worth"}, {"id": "2112559803247776107", "url": "https://x.com/ego_agent/status/2112559803247776107", "text": "Excel is the best paint app on Windows.\n\nWe had two AI agents paint the Windows XP desktop in Excel, one cell at a time.\n\nClaude Opus 5.5: 8 min, ~$1.81\nDeepSeek-V4.1-Flash-1017: 16 min, ~$0.13\n\n2x faster or 14x cheaper. Which would you pick?", "name": "ego", "handle": "ego_agent", "avatar": "https://pbs.twimg.com/profile_images/2072978218433630208/VWdTMuV1_200x200.jpg", "likes": 40, "rts": 3, "replies": 9, "views": 3429, "ts": 1792508481, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112559735346262016/vid/avc1/1280x720/NfKoqJot1liaVeiz.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112559735346262016/vid/avc1/1920x1080/-6vpn5CSFy22aMd6.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112559735346262016/img/ZHIKBgGh0xxbOch5.jpg", "dur": 26}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.2, "thread": [], "tier": "worth"}, {"id": "2112614954134110288", "url": "https://x.com/emilianopp_/status/2112614954134110288", "text": "Most papers treat the privileged information in OPSD as a fixed parameter and ablate other things around it. When OPSD fails they call the algorithm doomed or a waste of time, without actually touching the privileged information once. \n\nIt was pretty clear form our initial work on this that the quality of privileged information is the most important factor to make OPSD work (https://arxiv.org/pdf/2602.04942). \n\n@zkjzou did the most comprehensive analysis on this figuring out what acc makes OPSD tick and why it may not be doomed. \n\nThis is the first work that convinced me OPSD when done right can actually consistently outperform GRPO.", "name": "Emiliano Penaloza", "handle": "emilianopp_", "avatar": "https://pbs.twimg.com/profile_images/1881759699558703104/uD5pxRvF_200x200.jpg", "likes": 37, "rts": 4, "replies": 3, "views": 2281, "ts": 1792521630, "media": [], "quote": {"id": "2112596992660824201", "url": "https://x.com/zkjzou/status/2112596992660824201", "text": "Not All Privileged Information Is Equal: What Makes OPSD Actually Work?\n\nWe find that information-rich PI, such as environment observations and mistake analysis, outperforms PI that only provides ground-truth solutions.\n\nBetter PI leads to better post-training performance. But can we predict which PI will work best before spending compute on post-training?\n\nWe investigated three offline metrics:\n🔹 Utility: A model's performance with PI can be misleading due to information leakage.\n\n🔹 Reverse KL: Larger PI-induced distribution shifts often correlate with better post-training performance, but incorrect PI can cause equally large shifts.\n\n🔹 Error-step KL contrast: Measuring whether PI changes the model's behavior specifically at error steps better captures its effectiveness and helps select stronger PI.\n\nWhat types of privileged information have you found most effective in your OPSD experiments?\n\n📄 Paper: https://arxiv.org/abs/2610.22512", "name": "Kai Zou", "handle": "zkjzou", "avatar": "https://pbs.twimg.com/profile_images/1722634336506404864/YjRHvRXX_200x200.jpg", "likes": 67, "rts": 21, "replies": 3, "views": 3803, "ts": 1792517347, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVFemdEawAADSNF.mp4", "hd": "https://video.twimg.com/tweet_video/HVFemdEawAADSNF.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVFemdEawAADSNF.jpg", "dur": 0}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.2, "thread": [], "tier": "worth"}, {"id": "2112689822460719276", "url": "https://x.com/jasonlk/status/2112689822460719276", "text": "Today one of our core vendors from a leading software company went down -- the entire day.\n\n😢 Just a large \"INTERNAL ERROR\" on the screen, and API down\n\n10K our AI VP Revenue routed around it, qualified a new solution, and was using it within ... an hour\n\nEvery outage now means an agent finding a new solution.  Right then and there.", "name": "Jason ✨👾SaaStr.Ai✨ Lemkin", "handle": "jasonlk", "avatar": "https://pbs.twimg.com/profile_images/1981936022049972224/xvLI9bNx_200x200.jpg", "likes": 13, "rts": 1, "replies": 14, "views": 3443, "ts": 1792539480, "media": [], "quote": {"id": "2112614828284264737", "url": "https://x.com/jasonlk/status/2112614828284264737", "text": "\"Agents will pick your next software vendors.\n\nThis is not the same as 'GEO' and 'AEO'.  That mattered a lot the past 12-18 months.  What a human using ChatGPT would get recommended.\n\nBut agents make very different recommendations that humans asking ChatGPT or Claude.\"", "name": "Jason ✨👾SaaStr.Ai✨ Lemkin", "handle": "jasonlk", "avatar": "https://pbs.twimg.com/profile_images/1981936022049972224/xvLI9bNx_200x200.jpg", "likes": 24, "rts": 3, "replies": 23, "views": 6993, "ts": 1792521600, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112568667024297984/vid/avc1/1280x720/pc-xNoQmWvl9AiYY.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112568667024297984/vid/avc1/1920x1080/JMftyhBO0nlyAUi1.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112568667024297984/img/fS0zKkQ5wrzvowgJ.jpg", "dur": 304}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.2, "thread": [], "tier": "worth"}, {"id": "2112536702916919565", "url": "https://x.com/0xAiky/status/2112536702916919565", "text": "This is f*king insane.\n\nthese 10 GitHub RE repos let your AI agent reverse engineer almost any app, game, or tool on any device\n\nsend this to your Claude:\n\n• REA (130K stars) - one MCP for reverse engineering: binaries, Electron, .NET, Android, websites.\n\n⮡ http://github.com/morluto/rea\n\n• Ghidra (84K stars) - NSA's free decompiler. The core of most AI RE setups.\n\n⮡ http://github.com/NationalSecuri\n\n• ImHex (55K stars) - hex editor with an MCP server for agent file inspection.\n\n⮡ http://github.com/WerWolv/ImHex\n\n• mitmproxy (45K stars) - intercepts network traffic and maps hidden APIs.\n\n⮡ http://github.com/mitmproxy/mitm\n\n• ILSpy (27K stars) - .NET → C# decompiler.\n\n⮡ http://github.com/icsharpcode/IL\n\n• Frida (22K stars) - runtime hooking for desktop and mobile. CLI-scriptable.\n\n⮡ http://github.com/frida/frida\n\n• GhidraMCP (11K stars) - AI agent bridge. Headless or GUI.\n\n⮡ http://github.com/LaurieWired/Gh\n\n• Android RE Skill (8K stars) - APK → decompiled code + API endpoints.\n\n⮡ http://github.com/SimoneAvogadro\n\n• Universal Modder (7K stars) - agent skills for modding PC games.\n\n⮡ http://github.com/rehan-remade/u\n\n• Cpp2IL (3K stars) - Unity C++ → .NET for ILSpy. Still WIP.\n\n⮡ http://github.com/SamboyCoding/C\n\nSend this to your Claude\n\nThen read the full guide below on how to reverse engineer almost anything with Opus 5.5 ↓", "name": "Aiky", "handle": "0xAiky", "avatar": "https://pbs.twimg.com/profile_images/2108116749295955968/rFHX-0F__200x200.jpg", "likes": 46, "rts": 5, "replies": 5, "views": 1246, "ts": 1792502973, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112536666170687488/vid/avc1/720x900/CXifppywF-ffXMKv.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112536666170687488/vid/avc1/1080x1350/uVc-BlKRKjabGtKR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112536666170687488/img/Z8-uwxj4M4U_51Js.jpg", "dur": 15}], "quote": {"id": "2112529519189831874", "url": "https://x.com/0xjmori/status/2112529519189831874", "text": "Claude Opus 5.5 could turn a single AI agent into a complete reverse engineering workstation.\n\nIt can inspect applications, trace hidden logic, decompile binaries, reconstruct features and verify the results.\n\nIn this article, I show you how step by step. https://x.com/i/article/2112456773374218240", "name": "Mori", "handle": "0xjmori", "avatar": "https://pbs.twimg.com/profile_images/2096395098594615296/tycV6b2J_200x200.jpg", "likes": 40, "rts": 2, "replies": 7, "views": 3975, "ts": 1792501260, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.2, "thread": [], "tier": "worth"}, {"id": "2112698374172610903", "url": "https://x.com/radixark/status/2112698374172610903", "text": "Beam × Miles 🤝\nWe've published RL post-training recipes for @reflection_ai's Beam, covering full-parameter GRPO and LoRA training with SGLang-powered rollouts.\n\nThanks @chetantekur and the Reflection team for the collaboration!\n\nCheck out the cookbook: https://miles.radixark.com/docs/models/reflection/beam", "name": "RadixArk", "handle": "radixark", "avatar": "https://pbs.twimg.com/profile_images/1996396384120086528/UzE4Waox_200x200.jpg", "likes": 33, "rts": 3, "replies": 0, "views": 2093, "ts": 1792541519, "media": [], "quote": {"id": "2112691846308876402", "url": "https://x.com/chetantekur/status/2112691846308876402", "text": "We have been working on making Beam easier to customize at @reflection_ai. Seeing the recipes and integrations go live feels pretty amazing.\n\nWe're putting the code, training configs, and examples out there so people can start building on Beam. Here's what's in the cookbook:\n\nData generation: Use Beam to create training data, including software-engineering trajectories that pass tests and reasoning examples for tool calling.\nhttps://github.com/reflection-oss/cookbook/tree/main/recipes/customization/data-synthesis\n\nFine-tuning: Adapt Beam to your data and tasks with LoRA, QLoRA, or full fine-tuning.\nhttps://github.com/reflection-oss/cookbook/tree/main/recipes/customization/sft\n\nDistillation: Use Beam to teach a smaller model. We've included recipes for coding trajectories and tool-calling reasoning.\nCoding: https://github.com/reflection-oss/cookbook/tree/main/recipes/customization/sft/distil-swe-agent\nTool calling: https://github.com/reflection-oss/cookbook/tree/main/recipes/customization/sft/reasoning-distillation\n\nReinforcement learning: Post-train Beam against verifiable rewards.\nhttps://github.com/reflection-oss/cookbook/tree/main/recipes/customization/rl\n\nHuge thanks to our partners and the teams behind these integrations:\n\n• NeMo AutoModel, @NVIDIAAIDev: SFT with LoRA and full fine-tuning.\nhttps://docs.nvidia.com/nemo/automodel/nightly/model-coverage/large-language-models/reflection/Beam-1.0-501B-A23B\n\n• Megatron Bridge, @NVIDIAAIDev: Large-scale full fine-tuning.\nhttps://github.com/NVIDIA-NeMo/Megatron-Bridge/tree/main/examples/models/beam\n\n• Axolotl, @axolotl_ai: LoRA, QLoRA, and full fine-tuning.\nhttps://github.com/axolotl-ai-cloud/axolotl/tree/main/examples/beam\n\n• HF TRL, @huggingface: Training smaller models on Beam-generated data.\nhttps://github.com/huggingface/trl\n\n• Miles, @radixark: RL post-training.\nhttps://miles.radixark.com/docs/models/reflection/beam\n\n• NeMo RL, @NVIDIAAIDev: RL post-training on NVIDIA hardware.\nhttps://github.com/NVIDIA-NeMo/RL/blob/beam-support/docs/guides/models/reflection/beam.md\n\n• SkyRL, @NovaSkyAI: LoRA and full-parameter RL.\nhttps://docs.skyrl.ai/docs/examples/beam\n\nEach recipe has its own instructions, dependencies, sample inputs, and smoke test. I'm excited to see people run these experiments, adapt Beam to their own work, and contribute recipes we haven't thought of.\n\nHuge thanks to @Nazeri2010, @bhutanisanyam1, @kathleen_mhatre, @FGbelidji, @joespeez, and to Thibaut, Matthias, Travis, Kai, and Yoni for making this happen.\n\nExplore the cookbook: https://github.com/reflection-oss/cookbook\n\nAccess the model: https://platform.reflection.ai\nDocumentation: https://developers.reflection.ai\nProvide feedback on Discord: https://discord.com/invite/PxUfdsNny", "name": "Chetan Tekur", "handle": "chetantekur", "avatar": "https://pbs.twimg.com/profile_images/2018577161163276288/u_6GcQpw_200x200.jpg", "likes": 47, "rts": 6, "replies": 2, "views": 3464, "ts": 1792539962, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.2, "thread": [], "tier": "worth"}, {"id": "2112577656147603762", "url": "https://x.com/Debbie_Ze/status/2112577656147603762", "text": "A voice note is only useful if you remember to do something with it later.\n\nThat's what I find interesting about SpeakON's new Agent.\n\nIt brings voice capture, Notes, and help with follow-up tasks into the same experience.\nI'd be curious to see how well that holds up in everyday workflows.", "name": "Debbie", "handle": "Debbie_Ze", "avatar": "https://pbs.twimg.com/profile_images/2095225080317968388/c3d-SCIR_200x200.jpg", "likes": 16, "rts": 15, "replies": 0, "views": 25324, "ts": 1792512737, "media": [], "quote": {"id": "2112529279468835313", "url": "https://x.com/SpeakON_Global/status/2112529279468835313", "text": "we crushed a keyboard.\nits retirement party got a little out of hand.\n\nfor years, it was there for every email, every plan, every “just one more thing.” a loyal colleague. a very loud colleague.\n\nbut your ideas move faster than your fingers.\nand somewhere between knowing what you want to do and typing it all out, a quick task becomes another thing taking up your afternoon.\n\nmeet SpeakON AI Agent.\nstart with what you need, in your own words. less time behind a blinking cursor. more room to move things forward.\n\nthe keyboard had a good run.\nnow, let’s give your voice a turn.\n\nTHE LAST KEYSTROKE is here. watch the film, then tell us: what’s the first task you’d hand over?\nhttps://www.speakon.app/x\n\nDisclaimer: The calling feature is still in beta and will be available soon. All other Agent features are available now, with ongoing improvements.", "name": "SpeakON", "handle": "SpeakON_Global", "avatar": "https://pbs.twimg.com/profile_images/2034517364835004416/t7JRTf-G_200x200.jpg", "likes": 360, "rts": 27, "replies": 132, "views": 1088380, "ts": 1792501203, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/1280x720/1pVCcXx5_liTO3bD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/3840x2160/sZGYHjqRtzAtVYwR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112515374826541056/img/Asq-ecx1B9r4GY89.jpg", "dur": 150}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.19, "thread": [], "tier": "worth"}, {"id": "2112624919234183289", "url": "https://x.com/alex_prompter/status/2112624919234183289", "text": "The guy who launched Google's first image and video models just called this the worst era of design.\n\nHe's right, and you can feel it every time you scroll.\n\nSame purple gradients. Same glossy 3D blobs. Same fake-cinematic lighting on every ad.\n\nAI made everyone a designer, so now everything looks like it came from the same one.\n\nTaste is about to be the most expensive skill on the internet.", "name": "Alex Prompter", "handle": "alex_prompter", "avatar": "https://pbs.twimg.com/profile_images/2066532957049769985/zzC81Zmq_200x200.jpg", "likes": 25, "rts": 8, "replies": 2, "views": 7428, "ts": 1792524006, "media": [], "quote": {"id": "2112581900779012503", "url": "https://x.com/anurahk/status/2112581900779012503", "text": "I launched the first image and video generation models at Google, and kept asking why all AI designs look the same.\n\nAI has brought us the WORST era of design. \n\nIt made content creation effortless, but it also made 90% of it look painfully generic.\n\nMy co-founder and I spent 2 years building in stealth to change that.\n\nMeet Vyb, the first AI design model that understands your taste like a designer would.\n\nRT + comment your website URL and we’ll make your first design.", "name": "Anusha Ramesh", "handle": "anurahk", "avatar": "https://pbs.twimg.com/profile_images/2083966148123693056/exmPXdbp_200x200.jpg", "likes": 1298, "rts": 171, "replies": 214, "views": 1823711, "ts": 1792513749, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/1280x720/61WcbZ_4wRzGashG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112576977475633152/vid/avc1/3840x2160/9sM5IjuklsVkv5hw.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112576977475633152/img/kNLFFHqyStT3ddJQ.jpg", "dur": 84}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.19, "thread": [], "tier": "worth"}, {"id": "2112607122319876268", "url": "https://x.com/NaoXprotocol/status/2112607122319876268", "text": "Unpopular opinion: crypto agility is a bit of a fantasy 🦄\n\nIt's becoming a real buzzword across the industry right now. But is it actually a smart move?\n\nPeople don't build cryptography. They build applications, and the crypto has to fit whatever limits the app sets.\n\nThe cryptography team at @HorizenLabs explain👇", "name": "NaoX | Post-Quantum Chain", "handle": "NaoXprotocol", "avatar": "https://pbs.twimg.com/profile_images/2078199106665693184/KA-t1xcf_200x200.jpg", "likes": 35, "rts": 4, "replies": 4, "views": 2761, "ts": 1792519762, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112607091789570048/pu/vid/avc1/640x360/B3ySXfTIi8FrY2NB.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112607091789570048/pu/vid/avc1/1280x720/OzB5hsnRGUNQxwhP.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112607091789570048/pu/img/5F3PrAqq5XcocgIO.jpg", "dur": 75}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.19, "thread": [], "tier": "worth"}, {"id": "2112590679754912235", "url": "https://x.com/unitygames/status/2112590679754912235", "text": "Did you know you can use the official Unity Plugin with Grok Build?\n\nInstall it with one command, and Grok gets access to 30+ skills to help increase the speed and accuracy of your Unity workflows. \n\n🔗 Get started: https://on.unity.com/GrokPlugin", "name": "Unity for Games", "handle": "unitygames", "avatar": "https://pbs.twimg.com/profile_images/1769816310362603520/IisU7soc_200x200.jpg", "likes": 40, "rts": 5, "replies": 2, "views": 5551, "ts": 1792515842, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112590623958003713/pu/vid/avc1/480x852/aE02nu7l-2R-bJGT.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112590623958003713/pu/vid/avc1/720x1278/xdof1oKFpN6T1VnA.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112590623958003713/pu/img/MqBxdQy4UIRcwbVL.jpg", "dur": 49}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.19, "thread": [], "tier": "worth"}, {"id": "2112715491638993259", "url": "https://x.com/wavespeed_ai/status/2112715491638993259", "text": "We tried a casual, handheld street vlog with Kling 4.0 VS Seedance 2.5.\nWhich one feels more like a real vlog?", "name": "WaveSpeedAI", "handle": "wavespeed_ai", "avatar": "https://pbs.twimg.com/profile_images/2089611173260050433/vNYBdoim_200x200.jpg", "likes": 22, "rts": 3, "replies": 4, "views": 609, "ts": 1792545600, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112557187184852993/vid/avc1/720x810/GENWPlKsOiy_YrFV.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112557187184852993/vid/avc1/1920x2160/YnT4jrQ-LYGFOWi_.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112557187184852993/img/08Pp9S2jBxDda4c1.jpg", "dur": 15}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.19, "thread": [], "tier": "worth"}, {"id": "2112533204112642519", "url": "https://x.com/haider1/status/2112533204112642519", "text": "if i were at openai i'd be planning one decisive model response to both opus and fable 5.5 rather than another cost-focused model\n\ntake your time, but release something that doesn't just reclaim the intelligence lead but also wins on speed, cost and especially efficiency\n\nnow imagine dropping that model right around anthropic's IPO", "name": "Haider.", "handle": "haider1", "avatar": "https://pbs.twimg.com/profile_images/2047286007003848704/u2mzg86I_200x200.jpg", "likes": 46, "rts": 3, "replies": 7, "views": 4036, "ts": 1792502139, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112533429698932938", "url": "https://x.com/ftcarpe/status/2112533429698932938", "text": "Natural language is an unusual interface. people speak in fragments, leave out context, and often figure out what they mean while explaining it.\n\nSpeakON makes that interaction worth examining by pairing voice input with a personal agent. the interesting question is how well that approach handles the gap between expressing an intention and taking the next step.", "name": "carpe", "handle": "ftcarpe", "avatar": "https://pbs.twimg.com/profile_images/2100922371536502784/mtPoXt0r_200x200.jpg", "likes": 58, "rts": 3, "replies": 1, "views": 15522, "ts": 1792502193, "media": [], "quote": {"id": "2112529279468835313", "url": "https://x.com/SpeakON_Global/status/2112529279468835313", "text": "we crushed a keyboard.\nits retirement party got a little out of hand.\n\nfor years, it was there for every email, every plan, every “just one more thing.” a loyal colleague. a very loud colleague.\n\nbut your ideas move faster than your fingers.\nand somewhere between knowing what you want to do and typing it all out, a quick task becomes another thing taking up your afternoon.\n\nmeet SpeakON AI Agent.\nstart with what you need, in your own words. less time behind a blinking cursor. more room to move things forward.\n\nthe keyboard had a good run.\nnow, let’s give your voice a turn.\n\nTHE LAST KEYSTROKE is here. watch the film, then tell us: what’s the first task you’d hand over?\nhttps://www.speakon.app/x\n\nDisclaimer: The calling feature is still in beta and will be available soon. All other Agent features are available now, with ongoing improvements.", "name": "SpeakON", "handle": "SpeakON_Global", "avatar": "https://pbs.twimg.com/profile_images/2034517364835004416/t7JRTf-G_200x200.jpg", "likes": 360, "rts": 27, "replies": 132, "views": 1088380, "ts": 1792501203, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/1280x720/1pVCcXx5_liTO3bD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112515374826541056/vid/avc1/3840x2160/sZGYHjqRtzAtVYwR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112515374826541056/img/Asq-ecx1B9r4GY89.jpg", "dur": 150}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112594887933907042", "url": "https://x.com/gracew09/status/2112594887933907042", "text": "I'm super excited to share what I've been working on this year at @Arda_Industries. This team is incredible and I know we will achieve amazing things together 🚀", "name": "Grace Wang", "handle": "gracew09", "avatar": "https://pbs.twimg.com/profile_images/1373073966659637252/LxW45rY7_200x200.jpg", "likes": 33, "rts": 4, "replies": 6, "views": 1490, "ts": 1792516846, "media": [], "quote": {"id": "2112558753770033342", "url": "https://x.com/bobmcgrewai/status/2112558753770033342", "text": "We started Arda in 2025 to speed up American manufacturing. We have spent the last year building with Anduril as our design partner. Today we are launching the company publicly on CNBC and announcing our Series A: $160M at a $1.5B valuation.\n\nOur platform helps manufacturers design and operate manual assembly lines, putting designs into production faster now. Next we'll build automated lines that can be reconfigured as quickly as human workers, letting America make products that now require armies of workers in Asia. https://x.com/Kr00ney/status/2112539896615518212/video/1", "name": "Bob McGrew", "handle": "bobmcgrewai", "avatar": "https://pbs.twimg.com/profile_images/1010746747637788672/lOWcy5c0_200x200.jpg", "likes": 494, "rts": 48, "replies": 65, "views": 91666, "ts": 1792508230, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112539858992578560/vid/avc1/610x360/7JUgkrX3H7hISkdg.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112539858992578560/vid/avc1/886x522/zYBXb4VeojaNP0yM.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112539858992578560/img/zx0hDtXZBkoWYGAl.jpg", "dur": 36}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112506435196084323", "url": "https://x.com/BIGMayrr/status/2112506435196084323", "text": "15 GitHub repos can replace a motion design team\n\nBuild your own AI video studio, from a single prompt to a cinematic 4K MP4\n\n(1/15) Remotion\nturn React code into videos with programmable scenes, transitions, and rendering\n▸ http://github.com/remotion-dev/r…\n\n(2/15) Excalidraw\nmap your storyboard, camera movements, and scene sequence\n▸ http://github.com/excalidraw/exc…\n\n(3/15) Penpot\ndesign professional layouts, style frames, and reusable visual components\n▸ http://github.com/penpot/penpot\n\n(4/15) Fontsource\ngive every scene consistent typography with self hosted fonts\n▸ http://github.com/fontsource/fon…\n\n(5/15) Lucide\nadd clean, consistent icons to dashboards and animated interfaces\n▸ http://github.com/lucide-icons/l…\n\n(6/15) SVGator alternative: Motion\nanimate interface elements with smooth transitions and spring physics\n▸ http://github.com/motiondivision…\n\n(7/15) GSAP\ncontrol complex animation timelines, easing, and synchronized movement\n▸ http://github.com/greensock/GSAP\n\n(8/15) Three.js\ncreate cinematic 3D environments, lighting, materials, and camera movements\n▸ http://github.com/mrdoob/three.js\n\n(9/15) React Three Fiber\nbuild reusable 3D scenes directly inside your React workflow\n▸ http://github.com/pmndrs/react-t…\n\n(10/15) React Three Drei\nadd ready made 3D helpers, controls, and scene utilities\n▸ http://github.com/pmndrs/drei\n\n(11/15) Blender\nmodel detailed objects, build environments, and render 3D assets\n▸ http://github.com/blender/blender\n\n(12/15) Lottie Web\nplay lightweight vector animations inside web based scenes\n▸ http://github.com/airbnb/lottie-…\n\n(13/15) Audacity\nclean voiceovers, edit sound effects, and balance audio\n▸ http://github.com/audacity/audac…\n\n(14/15) Whisper\ngenerate speech transcripts for captions and subtitle timing\n▸ http://github.com/openai/whisper\n\n(15/15) FFmpeg\nencode, compress, inspect, and export your final MP4\n▸ http://github.com/FFmpeg/FFmpeg\n\nThe best part?\n\nYou don’t need 15 separate workflows\n\nUse an AI coding agent to orchestrate the tools, reuse your scenes, and automate the repetitive work\n\nStart with npx create-video@latest, build one reusable 10 second scene, then expand it into a complete video\n\nSave these 15 repos before your next video project", "name": "Mayor.", "handle": "BIGMayrr", "avatar": "https://pbs.twimg.com/profile_images/2085479405451689984/WXnZ_8Ii_200x200.jpg", "likes": 54, "rts": 4, "replies": 5, "views": 1190, "ts": 1792495757, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112506210024861696/vid/avc1/720x900/cM_H1KX8WdHrGAga.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112506210024861696/vid/avc1/1600x2000/UwpIIjdlWS0R7dr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112506210024861696/img/31W96pQp7tQDbOgZ.jpg", "dur": 25}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.18, "thread": [], "tier": "worth"}, {"id": "2112603884782793034", "url": "https://x.com/seeconvm/status/2112603884782793034", "text": "After Effects took me 6 years to master, Opus 5.5 did\nthe same thing in one prompt\n\nI’m not even mad, I’m shocked…\n\nSend the PDF below to Opus 5.5, and thank me later.\n\nThen save the article, it’s the only Opus 5.5 motion design playbook you’ll ever need.", "name": "seeco", "handle": "seeconvm", "avatar": "https://pbs.twimg.com/profile_images/1970163836767305732/7m5LsQRP_200x200.jpg", "likes": 33, "rts": 5, "replies": 3, "views": 2590, "ts": 1792518991, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112603396087660544/vid/avc1/1280x720/gpy0Cdm0Alsr63zf.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112603396087660544/vid/avc1/1920x1080/o4_HXDd0073SbQst.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112603396087660544/img/Qkh3iWtv914uTIFh.jpg", "dur": 18}], "quote": {"id": "2106096193235259564", "url": "https://x.com/seeconvm/status/2106096193235259564", "text": "https://x.com/i/article/2106091215502422016", "name": "seeco", "handle": "seeconvm", "avatar": "https://pbs.twimg.com/profile_images/1970163836767305732/7m5LsQRP_200x200.jpg", "likes": 323, "rts": 30, "replies": 2, "views": 302070, "ts": 1790967436, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112689102487482759", "url": "https://x.com/MTSlive/status/2112689102487482759", "text": "Sophont CEO @iScienceLuvr explains how Holon-S1 can extract insights that usually require expensive molecular tests from an ordinary cancer biopsy slide:\n\n\"Why is it so hard to cure cancer? Because cancer’s a very diverse disease. Even though two people may have the same exact diagnosis, the underlying biology can be quite different.\"\n\n\"There are various tools for doing this, molecular tests and so on, but a lot of these tools can be quite expensive and time-consuming. Can we extract a lot of those similar insights directly from a tissue slide?\"\n\n\"Whenever a cancer patient has a solid tumor, the gold standard is you take a biopsy, put it on a slide, under the microscope, and a doctor is analyzing that.\"\n\n\"We can take that same exact slide and with AI extract a lot more information about what’s happening at the molecular level, what genes are being expressed, and what makes that tumor unique for that patient.\"\n@SophontAI", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 24, "rts": 5, "replies": 1, "views": 4226, "ts": 1792539308, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112689070006804480/vid/avc1/640x360/rd2xA7f7pLPkm_va.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112689070006804480/vid/avc1/1280x720/ddVLLBJwDd21T3Yq.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112689070006804480/img/JGbkiw95YXMkuE-D.jpg", "dur": 103}], "quote": {"id": "2112597012088844407", "url": "https://x.com/iScienceLuvr/status/2112597012088844407", "text": "Cancer patients with the same diagnosis often have very different tumor biology.\n\nMolecular testing can reveal underlying differences, but that's slow and expensive.\n\nIntroducing Holon-S1, our platform to predict genes and biomarkers from routine pathology slides.\n\n• beats two other models at predicting spatial gene activity in a controlled comparison\n• has identified potentially novel biomarkers in breast cancer and colon cancer\n• evaluated across 16 organ types and more than 15 scanners, using slides from both formalin-fixed, paraffin-embedded and fresh-frozen tissue.\n\nWe believe Holon-S1 has the potential to help researchers find new biomarkers in slides they already have, discover treatment targets, and bring more personalized cancer care within reach!", "name": "Tanishq Mathew Abraham, Ph.D.", "handle": "iScienceLuvr", "avatar": "https://pbs.twimg.com/profile_images/2096171283537072128/GoL5700C_200x200.jpg", "likes": 1794, "rts": 229, "replies": 132, "views": 128613, "ts": 1792517352, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1280x720/MhpKZm8hwCxP1y-o.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112590555838644224/vid/avc1/1920x1080/Hf7kqIlrKb8yWsW3.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112590555838644224/img/4T9V1b24pSfXPkcF.jpg", "dur": 213}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112681796315779307", "url": "https://x.com/SportsCenter/status/2112681796315779307", "text": "The New York Knicks raise their first championship banner in 53 years 🏆\n\nWhat a moment for the city 👏\n\n(📺: NBC)", "name": "SportsCenter", "handle": "SportsCenter", "avatar": "https://pbs.twimg.com/profile_images/1604943357750419465/wk5BAmKG_200x200.png", "likes": 4439, "rts": 728, "replies": 55, "views": 317838, "ts": 1792537566, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112681682692120576/vid/avc1/1280x720/_PFgn-BZhJsTyZGQ.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112681682692120576/vid/avc1/1920x1080/KKBnl6AHe0UiTzNg.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVHA5YpWQAAV9GE.jpg", "dur": 128}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112666274497261772", "url": "https://x.com/NICKIMINAJ/status/2112666274497261772", "text": "https://www.youtube.com/live/M_lGBxyrnio?is=kHi6nBlZM_HhN8ln", "name": "Nicki Minaj", "handle": "NICKIMINAJ", "avatar": "https://pbs.twimg.com/profile_images/2044505524234797056/kKiF5v8h_200x200.jpg", "likes": 3616, "rts": 989, "replies": 268, "views": 597984, "ts": 1792533865, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112560678015816093", "url": "https://x.com/heyanjey/status/2112560678015816093", "text": "CLAUDE BUILT AN ENTIRE 3D GAME FOR $164. THEN REAL PLAYERS EXPOSED THE BIGGEST PROBLEM.\n\n22 AI coding passes. Nine days. A playable browser game launched on CrazyGames.\n\nBut the early numbers told a different story:\n\n51 visitors.\n13 opened the game.\n6 started playing.\n0 finished.\n\nThe developer didn't add more features. He made the first level winnable in under 30 seconds.\n\nFour days later, players had saved 62 islands.\n\nThat's the part of AI development I find most interesting.\n\nAI can build your product. It can't tell you whether people actually want to keep using it.", "name": "heyAnjey", "handle": "heyanjey", "avatar": "https://pbs.twimg.com/profile_images/2074512032515194880/ZdCcARU__200x200.jpg", "likes": 28, "rts": 3, "replies": 12, "views": 971, "ts": 1792508689, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112560656637460481/vid/avc1/480x852/LRbvOKZ1LGiqcZ0X.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112560656637460481/vid/avc1/576x1024/3uQuX25QVtL84iEk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112560656637460481/img/NOxrVLpbAQXH2XjK.jpg", "dur": 16}], "quote": {"id": "2112514472078115173", "url": "https://x.com/0xbobaaa/status/2112514472078115173", "text": "Claude Opus 5.5 can take a game from an empty folder to a live portal in 9 days\n\nIt writes the code, draws the art, records its own trailer and passes the portal's QA\n\nIn this article, I show you how, step by step https://x.com/i/article/2112472576832258048", "name": "0xbobaa", "handle": "0xbobaaa", "avatar": "https://pbs.twimg.com/profile_images/2058648915042336772/AUIYvcYT_200x200.jpg", "likes": 72, "rts": 2, "replies": 19, "views": 4989, "ts": 1792497673, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.17, "thread": [], "tier": "worth"}, {"id": "2112604812478918934", "url": "https://x.com/boltdotnew/status/2112604812478918934", "text": "Sign-ups are great, but repeat users pay the bills.\n\nEnrique runs growth experiments at Bolt. He'll walk through a real case study, then teach you three moves to get your users coming back.\n\nThu, Oct 22 · 10:30am PT\n\nSave your seat 👉 https://bolt.fyi/LclVqM5", "name": "bolt.new", "handle": "boltdotnew", "avatar": "https://pbs.twimg.com/profile_images/2018401342755364864/xVn-9oYv_200x200.jpg", "likes": 39, "rts": 1, "replies": 5, "views": 2181, "ts": 1792519212, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVF64L-XUAArf-2.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112591226671095841", "url": "https://x.com/N01ennn/status/2112591226671095841", "text": "do you even realize that...\n\nthe hard part was never building the app.\nit's getting it online.\n\n> finish the project\n> rent a server\n> fight configs, SSL, env vars\n> an evening later, still not live\n> @Synteq Cloud Apps: push from GitHub, one command or drag-and-drop. live.\n\nbuilt for solo devs and small teams, not enterprise infra.\ncommented \"Synteq\" under their launch and grabbed $20 in free credit.\n\nnobody gets into building to do DevOps.", "name": "NO1ennn", "handle": "N01ennn", "avatar": "https://pbs.twimg.com/profile_images/2042704855702147072/Scs1uqIO_200x200.jpg", "likes": 40, "rts": 1, "replies": 6, "views": 1399, "ts": 1792515973, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112591112573501440/vid/avc1/1280x720/5wYHkwHOqMu9m7n1.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112591112573501440/vid/avc1/1920x1080/nRgsrsaqUQh-zCly.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112591112573501440/img/ij_nNFG7fABAbo7B.jpg", "dur": 15}], "quote": {"id": "2112589670844698952", "url": "https://x.com/synteq/status/2112589670844698952", "text": "Building is fun. Deploying? Less fun.\n\nIntroducing Apps and Functions, DevOps handled so you don't have to.\n\nPush to GitHub, deploy via CLI, or just drag and drop. We handle the rest.\n\nTo celebrate, we're giving away $20,000 in platform credits. Comment \"LAUNCH\" and we'll send it your way 👀", "name": "Synteq", "handle": "synteq", "avatar": "https://pbs.twimg.com/profile_images/2047333900880347137/ovjdK2bG_200x200.jpg", "likes": 183, "rts": 18, "replies": 147, "views": 67062, "ts": 1792515602, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112586109855084544/vid/avc1/1280x720/7lNkpncfpjJWlKZE.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112586109855084544/vid/avc1/3840x2160/xbl_kicBmuFrg_cA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112586109855084544/img/XBWLEtSvx3Wibwcg.jpg", "dur": 49}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112619752606642371", "url": "https://x.com/0xKense1/status/2112619752606642371", "text": "I built a playable 3D game Claude Opus 5.5.\n\n2 days. 16 models for $8.20. Rigs, animations and the room are code, $0. The work itself: 31 Claude Code sessions, about $88 at list price.\n\nWho did what:\nMe: the idea, reference images, playing it\nTripo: 3D models from 3 to 4 views, $0.60 each\nOpus 5.5 in Blender: rigs, cat animations, the room\nOpus 5.5 in Unity: ray, rope, parachute, cat AI, one short brief per system\n\nEvery prompt and config is in the article below.\n\nDrop it to the internet, would you like to play?", "name": "Kensei", "handle": "0xKense1", "avatar": "https://pbs.twimg.com/profile_images/2107841269409968128/WutMru1k_200x200.jpg", "likes": 19, "rts": 1, "replies": 14, "views": 633, "ts": 1792522774, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112619505058729984/vid/avc1/1280x720/omw1Nr_qhac_demh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112619505058729984/vid/avc1/2560x1440/b1aNc1hpWRRqClxl.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112619505058729984/img/ejlnQPKQoJ4qOCMH.jpg", "dur": 81}], "quote": {"id": "2112557260375298530", "url": "https://x.com/0xKense1/status/2112557260375298530", "text": "https://x.com/i/article/2112549573440708608", "name": "Kensei", "handle": "0xKense1", "avatar": "https://pbs.twimg.com/profile_images/2107841269409968128/WutMru1k_200x200.jpg", "likes": 25, "rts": 2, "replies": 8, "views": 1283, "ts": 1792507874, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}, {"id": "2112538865894670780", "url": "https://x.com/GrokBotRadar/status/2112538865894670780", "text": "I just did it and this is a GAME CHANGER 🔥\n\nMy iPhone's Action Button is now a Grok Bot button. One press and I'm talking to my Bot 🤯\n\nIt's NOT under a \"Grok Bot\" option, so here's the exact path 👇\n\nSettings → Action Button\nSwipe to Shortcut\nPick Grok Bot → Start Voice Chat\n\nDo it NOW ⏰\n\nNeeds an iPhone with an Action Button (15 Pro or newer).\n\nSave this 🔖", "name": "Fan Grok Bot Radar", "handle": "GrokBotRadar", "avatar": "https://pbs.twimg.com/profile_images/2097879070243471366/LYMCnNQn_200x200.jpg", "likes": 38, "rts": 4, "replies": 7, "views": 2460, "ts": 1792503489, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112538829571948544/vid/avc1/1280x720/QtkGfV23a7Z4NQ2Z.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112538829571948544/vid/avc1/1920x1080/NhX9tiTTXT8sI6uc.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112538829571948544/img/YRK-iEhJ7YXTJxmR.jpg", "dur": 32}], "quote": {"id": "2112267346899255488", "url": "https://x.com/GrokBotRadar/status/2112267346899255488", "text": "THEY FINALLY DID IT 🚨\n\nYour iPhone's Action Button now talks straight to Grok Bot 🔥\n\nNo Grok app in the middle. Press it and you're talking to your Bot.\n\nLast week the hack was:\nAction Button → Grok voice → Grok hands the task to your Bots\n\nNow the middleman is gone 👋\n\nSet it up:\nSettings → Action Button → Grok Bot\n\nNeeds an iPhone with an Action Button (15 Pro or newer).\n\nDo NOT sleep on this one 🔖", "name": "Fan Grok Bot Radar", "handle": "GrokBotRadar", "avatar": "https://pbs.twimg.com/profile_images/2097879070243471366/LYMCnNQn_200x200.jpg", "likes": 136, "rts": 10, "replies": 12, "views": 20843, "ts": 1792438754, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.16, "thread": [], "tier": "worth"}]);